package br.com.adminpool.repository;
import br.com.adminpool.model.CobrancaMensal; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.List; import java.util.Optional;
public interface CobrancaRepository extends JpaRepository<CobrancaMensal,Long> { List<CobrancaMensal> findAllByOrderByVencimentoAsc(); List<CobrancaMensal> findByReferenciaOrderByVencimentoAsc(String referencia); List<CobrancaMensal> findAllByOrderByReferenciaDescVencimentoAsc(); @Query("select c from CobrancaMensal c where c.referencia = :referencia or (c.vencimento < :inicioMes and c.status <> br.com.adminpool.model.StatusCobranca.PAGO) order by c.vencimento asc") List<CobrancaMensal> findMesAtualComAtrasos(@Param("referencia") String referencia, @Param("inicioMes") LocalDate inicioMes); boolean existsByClienteIdAndReferencia(Long clienteId, String referencia); Optional<CobrancaMensal> findByClienteIdAndReferencia(Long clienteId, String referencia); }
